$("checkSentenceButton")?.addEventListener("click",async()=>{
 const button=$("checkSentenceButton"),box=$("sentenceAiFeedback"),answer=String($("answerInput").value||"").trim(),sentenceIndex=active,source=ESSAY[sentenceIndex];
 saveCurrent();if(!answer){box.hidden=false;box.innerHTML='<p class="sentence-ai-note">Hãy viết câu tiếng Anh trước khi yêu cầu AI chấm.</p>';return;}
 button.disabled=true;const old=button.textContent;button.textContent="AI đang chấm câu…";box.hidden=false;box.innerHTML='<p class="sentence-ai-note">Đang kiểm tra ý nghĩa, ngữ pháp, collocation và độ tự nhiên của câu…</p>';
 try{const r=await api("/api/translation-sentence-feedback",{method:"POST",body:JSON.stringify({task:currentLesson.task,question:currentLesson.question,sentence:{en:source.en,vi:source.vi},answer})});const f=r.feedback||{},errors=Array.isArray(f.errors)?f.errors:[];box.innerHTML=`<div class="sentence-ai-feedback-head"><strong>Nhận xét riêng câu ${sentenceIndex+1}</strong><span class="ai-status ${escapeHtml(f.status||"minor_issue")}">${escapeHtml(({correct:"Đúng tốt",minor_issue:"Có thể cải thiện",error:"Cần sửa"})[f.status]||"Nhận xét")}</span></div><p>${escapeHtml(f.summary||"")}</p>${f.corrected_sentence?`<div class="ai-revision"><strong>Gợi ý sửa:</strong><p>${escapeHtml(f.corrected_sentence)}</p></div>`:""}${errors.length?`<h4>Điểm cần sửa</h4><ul>${errors.map(e=>`<li><strong>${escapeHtml(e.original||"")}</strong> → <strong>${escapeHtml(e.correction||"")}</strong><br>${escapeHtml(e.explanation||"")}</li>`).join("")}</ul>`:""}${Array.isArray(f.strengths)&&f.strengths.length?`<h4>Điểm tốt</h4><ul>${f.strengths.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>`:""}<small>Nhận xét học tập cho một câu; không phải điểm IELTS chính thức. Model: ${escapeHtml(r.model||"AI")}</small>`;
 }catch(e){box.innerHTML=`<p class="sentence-ai-note">Không chấm được câu này: ${escapeHtml(e.message)}</p>`;}
 finally{button.disabled=false;button.textContent=old;}
});
