$("resetButton").addEventListener("click",()=>{if(confirm("Xóa toàn bộ câu trả lời hiện tại và bắt đầu lại?")){answers=Array(ESSAY.length).fill("");lessonAnswers[currentLesson.id]=answers;active=0;hintShown=false;write("draftwise.lessonAnswers.v1",lessonAnswers);write(STORAGE.answers,answers);$("resultPanel").hidden=true;renderAll();showToast("Đã tạo lượt luyện tập mới.")}});
function switchView(view,options={}){
  const views=["library","practice","history","dashboard","mistakes","vocabularyNotes","settings","personalLessons","adminLessons","adminSettings"];
  views.forEach(v=>{const el=$(v+"View");if(el)el.hidden=v!==view;});
  document.querySelectorAll(".nav-item[data-view]").forEach(b=>b.classList.toggle("active",b.dataset.view===view));
  const labels={library:"Thư viện đề",practice:"Luyện dịch ngược",history:"Lịch sử bài làm",dashboard:"Dashboard",mistakes:"Sổ tay lỗi sai",vocabularyNotes:"Sổ tay ghi chú AI",settings:"Cài đặt tài khoản",personalLessons:"Quản lý đề của tôi",adminLessons:"Quản lý thư viện",adminSettings:"Bảo mật web"};
  const crumb=$("breadcrumbCurrent");if(crumb)crumb.textContent=labels[view]||"WriteWiser";
  if(view==="library"){
    if(libraryLoadState==="ready" && Date.now()-lastLibrarySyncAt>15000) loadServerLessons();
    else renderLibrary();
  }
  if(view==="history")renderHistory();
  if(view==="dashboard")renderDashboard();
  if(view==="mistakes")renderMistakes();
  if(view==="vocabularyNotes")loadVocabularyNotes();
  if(view==="settings"){updateSettingsAccess();}
  if(view==="personalLessons"){updatePersonalLessonsAccess();renderPersonalLessons();}
  if(view==="adminLessons"||view==="adminSettings"){
    if(!currentUser||currentUser.role!=="admin"){showToast("Trang này chỉ dành cho tài khoản admin.");switchView("library");return;}
    if(view==="adminLessons")renderAdminBuiltinLessons();
  }
  if(options.syncRoute!==false)wwSyncBrowserRoute(view);
  window.scrollTo({top:0,behavior:"smooth"});
}
function switchPracticeMode(mode,options={}){
  historyReviewMode=false;
  const historyEssayInput=$("independentEssayInput");if(historyEssayInput)historyEssayInput.readOnly=false;
  const clearEssayButton=$("clearIndependentButton");if(clearEssayButton)clearEssayButton.hidden=false;
  const independentSubmitRow=document.querySelector("#independentModePanel .independent-submit-row");if(independentSubmitRow)independentSubmitRow.hidden=false;
  practiceMode=mode==="independent"?"independent":"reverse";
  const reverse=practiceMode==="reverse";
  $("reverseModePanel").hidden=!reverse;
  $("independentModePanel").hidden=reverse;
  $("reverseModeButton").classList.toggle("active",reverse);
  $("independentModeButton").classList.toggle("active",!reverse);
  $("reverseModeButton").setAttribute("aria-selected",String(reverse));
  $("independentModeButton").setAttribute("aria-selected",String(!reverse));
  const sharedQuestion=document.querySelector(".task-card h2");if(sharedQuestion)sharedQuestion.hidden=!reverse;
  const sharedMeta=document.querySelector(".task-card .task-meta");if(sharedMeta)sharedMeta.hidden=!reverse;
  const resetButton=$("resetButton");if(resetButton)resetButton.hidden=!reverse;
  $("independentQuestionText").textContent=currentLesson.question;
  const isTask1=String(currentLesson.task).toLowerCase().includes("task 1");
  $("independentTaskLabel").textContent=isTask1?"Writing Task 1 Academic":"Writing Task 2";
  $("independentTimeLabel").textContent=(isTask1?"20":"40")+" phút gợi ý";
  $("independentTargetWords").textContent=isTask1?"150+":"250+";
  $("independentWordGuidance").textContent=isTask1?"Tối thiểu nên viết 150 từ":"Tối thiểu nên viết 250 từ";
  if(!reverse){
    const draft=independentDrafts[currentLesson.id];
    if(typeof draft==="string" && $("independentEssayInput").value.trim()==="")$("independentEssayInput").value=draft;
    updateIndependentMeta();independentStart=Date.now();
  }
  const heading=document.querySelector("#practiceView .page-heading h1");
  if(heading)heading.innerHTML=reverse?`Luyện viết, <em>${escapeHtml(currentLesson.title)}.</em>`:`Tự viết IELTS, <em>${escapeHtml(currentLesson.title)}.</em>`;
  const intro=document.querySelector("#practiceView .page-heading p");if(intro)intro.textContent=reverse?"Đọc toàn bộ bản dịch. Tự viết tiếng Anh. Chỉ xem kết quả khi bạn nộp cả bài.":"Không có bản dịch hoặc câu mẫu. Tự viết bài hoàn chỉnh rồi nộp để nhận phản hồi theo bốn tiêu chí IELTS.";
  if(options.syncRoute!==false)wwSyncBrowserRoute("practice");
}
function updateIndependentMeta(){
  const text=$("independentEssayInput").value;
  $("independentWordCount").textContent=wordCount(text);
  const elapsed=Math.max(0,Math.floor((Date.now()-independentStart)/1000));
  $("independentTimeSpent").textContent=`Thời gian phiên: ${String(Math.floor(elapsed/60)).padStart(2,"0")}:${String(elapsed%60).padStart(2,"0")}`;
}
$("reverseModeButton").addEventListener("click",()=>switchPracticeMode("reverse"));
$("independentModeButton").addEventListener("click",()=>switchPracticeMode("independent"));
$("independentEssayInput").addEventListener("input",()=>{independentDrafts[currentLesson.id]=$("independentEssayInput").value;write("draftwise.independentDrafts.v1",independentDrafts);updateIndependentMeta()});
$("independentEssayInput").addEventListener("input",markStudyDraftDirty);
$("clearIndependentButton").addEventListener("click",()=>{if(confirm("Xóa bài viết tự do đang nhập?")){$("independentEssayInput").value="";independentDrafts[currentLesson.id]="";write("draftwise.independentDrafts.v1",independentDrafts);updateIndependentMeta();showToast("Đã xóa bản nháp.")}});
setInterval(()=>{if(practiceMode==="independent"&&!$("independentModePanel").hidden&&!historyReviewMode)updateIndependentMeta()},1000);
// Capture text selected in either writing textarea or anywhere in the practice source.
function selectedContextFromText(value,start,end){
  const text=String(value||"");
  const left=Math.max(0,start-260),right=Math.min(text.length,end+260);
  return text.slice(left,right).trim();
}
function rememberInputSelection(field){
  if(!field || typeof field.selectionStart!=="number" || typeof field.selectionEnd!=="number")return;
  const start=field.selectionStart,end=field.selectionEnd;
  if(end<=start){if(lastStudySelection?.sourceKind==="textarea"&&lastStudySelection.sourceId===field.id)lastStudySelection=null;return;}
  const text=String(field.value||"").slice(start,end).trim();
  if(!text){if(lastStudySelection?.sourceKind==="textarea"&&lastStudySelection.sourceId===field.id)lastStudySelection=null;return;}
  lastStudySelection={text,sourceKind:"textarea",sourceId:field.id,context:selectedContextFromText(field.value,start,end),updatedAt:Date.now()};
}
function rememberPageSelection(){
  const selection=window.getSelection?.();
  const text=selection?String(selection.toString()||"").trim():"";
  if(!text){if(lastStudySelection?.sourceKind==="page")lastStudySelection=null;return;}
  let context="";
  try{
    const node=selection.anchorNode;
    const element=node?.nodeType===Node.ELEMENT_NODE?node:node?.parentElement;
    const scope=element?.closest?.(".essay-content,.current-source,.task-card,#independentQuestionText,.translation-panel,.writing-panel");
    context=String(scope?.innerText||element?.parentElement?.innerText||"").trim().slice(0,1000);
  }catch{}
  lastStudySelection={text,sourceKind:"page",sourceId:"",context,updatedAt:Date.now()};
}
document.addEventListener("selectionchange",rememberPageSelection);
["answerInput","independentEssayInput"].forEach(id=>{
  const field=$(id);if(!field)return;
  ["select","mouseup","keyup","touchend"].forEach(eventName=>field.addEventListener(eventName,()=>rememberInputSelection(field)));
});
function resolveStudySelection(preferredInputId){
  if(lastStudySelection?.text)return lastStudySelection;
  const domText=String(window.getSelection?.()?.toString()||"").trim();
  if(domText){rememberPageSelection();return lastStudySelection;}
  const preferred=$(preferredInputId);
  if(preferred && preferred.selectionEnd>preferred.selectionStart){rememberInputSelection(preferred);if(lastStudySelection?.sourceId===preferredInputId)return lastStudySelection;}
  return null;
}
function noteEscape(value){return escapeHtml(String(value||"")).replace(/\n/g,"<br>");}
function updateVocabNotesCount(){const count=$("vocabNotesCount");if(count)count.textContent=String(currentUser?vocabNotes.length:guestVocabNotes.length);}
async function generateVocabularyNoteFromText(options={}){
  const button=options.buttonId?$(options.buttonId):null;
  const status=options.statusId?$(options.statusId):null;
  const selectedText=String(options.text||"").trim();
  const context=String(options.context||"").trim().slice(0,1200);
  const source=options.source||"selection";
  if(!selectedText){
    if(status)status.textContent=source==="manual"?"Hãy nhập một từ, cụm từ, cấu trúc hoặc câu để AI tạo ghi chú.":"Hãy bôi đen một từ, cụm từ, vế câu hoặc câu trước khi nhấn lưu.";
    if(source==="manual")$("manualVocabNoteInput")?.focus();
    else showToast("Chưa có nội dung để tạo ghi chú.");
    return false;
  }
  if(selectedText.length>1800){if(status)status.textContent="Nội dung quá dài. Hãy rút gọn còn tối đa 1.800 ký tự.";return false;}
  if(button){button.disabled=true;button.dataset.oldText=button.textContent;button.textContent="AI đang tạo ghi chú…";}
  if(status)status.textContent=source==="manual"?"AI đang phân tích nội dung bạn nhập và tạo ghi chú…":"Đang phân tích đoạn được chọn và tạo ghi chú tiếng Việt…";
  try{
    const result=await api("/api/notes/generate",{method:"POST",body:JSON.stringify({selectedText,context,lessonTitle:String(options.lessonTitle||"").slice(0,200),task:String(options.task||"").slice(0,20),mode:String(options.mode||"manual").slice(0,30)})});
    const note=result.note;
    if(!note||!note.id)throw new Error("AI chưa trả về ghi chú hợp lệ.");
    if(currentUser){vocabNotes=[note,...vocabNotes.filter(item=>item.id!==note.id)];}
    else{
      guestVocabNotes=[note,...guestVocabNotes.filter(item=>item.id!==note.id)];
      try{localStorage.setItem(GUEST_VOCAB_NOTES_KEY,JSON.stringify(guestVocabNotes));}catch{throw new Error("Bộ nhớ trình duyệt đã đầy; không thể lưu ghi chú khách.");}
      vocabNotes=guestVocabNotes.slice();
    }
    if(source==="manual"){
      const searchInput=$("vocabNotesSearch"),filter=$("vocabNotesTypeFilter");
      if(searchInput)searchInput.value="";
      if(filter)filter.value="all";
    }
    updateVocabNotesCount();
    if(!$("vocabularyNotesView")?.hidden)renderVocabularyNotes();
    if(status)status.textContent=currentUser?"Đã tạo và lưu ghi chú vào tài khoản. Bạn có thể xem lại hoặc tìm ghi chú trong sổ tay.":"Đã tạo ghi chú và lưu trên trình duyệt này. Đăng nhập để đồng bộ giữa các thiết bị.";
    showToast(currentUser?"Đã lưu ghi chú AI vào tài khoản.":"Đã lưu ghi chú AI trên trình duyệt.");
    if(options.clearSelectionAfterSuccess)lastStudySelection=null;
    return true;
  }catch(error){if(status)status.textContent="Chưa lưu được ghi chú: "+error.message;showToast("Tạo ghi chú thất bại: "+error.message);return false;}
  finally{if(button){button.disabled=false;button.textContent=button.dataset.oldText||"✦ Tạo ghi chú AI";delete button.dataset.oldText;}}
}
async function generateSelectedVocabularyNote(preferredInputId,statusId,buttonId){
  const selection=resolveStudySelection(preferredInputId);
  if(!selection?.text){const status=$(statusId);if(status)status.textContent="Hãy bôi đen một từ, cụm từ, vế câu hoặc câu trước khi nhấn lưu.";showToast("Chưa có đoạn văn bản được chọn.");return false;}
  return generateVocabularyNoteFromText({text:selection.text,context:selection.context||"",lessonTitle:currentLesson?.title||"",task:currentLesson?.task||"",mode:practiceMode||"reverse",statusId,buttonId,source:"selection",clearSelectionAfterSuccess:true});
}
async function loadVocabularyNotes(){
  const generation=++vocabNotesLoadGeneration;
  const notice=$("vocabNotesStorageNotice"),status=$("vocabNotesStatus");
  if(notice)notice.hidden=!!currentUser;
  if(status)status.textContent="Đang tải sổ tay ghi chú…";
  if(currentUser){
    try{
      const result=await api("/api/notes");
      if(generation!==vocabNotesLoadGeneration)return;
      vocabNotes=Array.isArray(result.notes)?result.notes:[];
      if(status)status.textContent=`Đã tải ${vocabNotes.length} ghi chú từ database tài khoản.`;
    }catch(error){
      if(generation!==vocabNotesLoadGeneration)return;
      if(status)status.textContent="Không tải được ghi chú từ tài khoản: "+error.message;
      vocabNotes=[];
    }
  }else{
    guestVocabNotes=read(GUEST_VOCAB_NOTES_KEY,[]);if(!Array.isArray(guestVocabNotes))guestVocabNotes=[];
    vocabNotes=guestVocabNotes.slice();
    if(status)status.textContent=`${vocabNotes.length} ghi chú lưu trên trình duyệt hiện tại.`;
  }
  if(generation===vocabNotesLoadGeneration)renderVocabularyNotes();
}
function renderVocabularyNotes(){
  const root=$("vocabNotesList"),search=String($("vocabNotesSearch")?.value||"").trim().toLowerCase(),type=String($("vocabNotesTypeFilter")?.value||"all");
  if(!root)return;
  updateVocabNotesCount();
  const items=(Array.isArray(vocabNotes)?vocabNotes:[]).filter(note=>{
    const corpus=[note.expression,note.note,note.meaning_vi,note.usage,note.example_en,note.example_vi,note.selected_text,note.lessonTitle].join(" ").toLowerCase();
    const matchesSearch=!search||corpus.includes(search);
    const matchesType=type==="all"||String(note.category||"Cách diễn đạt").toLowerCase()===type.toLowerCase();
    return matchesSearch&&matchesType;
  });
  if(!items.length){root.innerHTML=`<div class="empty-state"><strong>${vocabNotes.length?"Không tìm thấy ghi chú phù hợp":"Sổ tay ghi chú đang trống"}</strong>${vocabNotes.length?"Hãy thử từ khóa hoặc bộ lọc khác.":"Bạn có thể nhấn “Tự nhập ghi chú” để chủ động tạo ghi chú, hoặc bôi đen từ/cụm từ/câu trong lúc luyện rồi chọn lưu ghi chú AI."}</div>`;return;}
  root.innerHTML=items.map((note,index)=>{
    const date=note.createdAt?new Date(note.createdAt).toLocaleString("vi-VN"):"Vừa lưu";
    const provenance=[note.task,note.lessonTitle].filter(Boolean).join(" · ");
    const category=note.category||"Cách diễn đạt";
    const expression=note.expression||note.selected_text||"Ghi chú";
    const explanation=[note.meaning_vi,note.note].filter(value=>String(value||"").trim()).join(" · ")||note.usage||note.example_vi||"Chưa có phần giải thích.";
    const detailsId=`vocabNoteDetails${index}`;
    return `<article class="vocab-note-card" data-note-card="${escapeHtml(note.id)}">
      <div class="vocab-note-compact-row">
        <span class="vocab-note-category" title="${escapeHtml(category)}">${escapeHtml(category)}</span>
        <h2 class="vocab-note-expression" title="${escapeHtml(expression)}">${escapeHtml(expression)}</h2>
        <p class="vocab-note-preview" title="${escapeHtml(explanation)}">${escapeHtml(explanation)}</p>
        <button type="button" class="button secondary vocab-note-detail-button" data-note-details="${escapeHtml(note.id)}" aria-expanded="false" aria-controls="${detailsId}">Chi tiết</button>
        <button type="button" class="button danger-quiet vocab-note-delete-button" data-note-delete="${escapeHtml(note.id)}" aria-label="Xóa ghi chú ${escapeHtml(expression)}">Xóa</button>
      </div>
      <div class="vocab-note-expanded" id="${detailsId}" hidden>
        <div class="vocab-note-detail-meta"><time>${escapeHtml(date)}</time>${provenance?`<span>${escapeHtml(provenance)}</span>`:""}</div>
        <section><h3>Ý nghĩa tiếng Việt</h3><p>${noteEscape(note.meaning_vi)||"Chưa có nghĩa tiếng Việt."}</p></section>
        ${note.note?`<section><h3>Ghi chú cần nhớ</h3><p>${noteEscape(note.note)}</p></section>`:""}
        <section><h3>Cách dùng</h3><p>${noteEscape(note.usage)||"Chưa có hướng dẫn cách dùng."}</p></section>
        <section class="vocab-note-example"><h3>Ví dụ</h3><p class="vocab-example-en">${noteEscape(note.example_en)||"Chưa có ví dụ."}</p>${note.example_vi?`<p class="vocab-example-vi">${noteEscape(note.example_vi)}</p>`:""}</section>
        <div class="vocab-note-actions"><button type="button" class="button secondary" data-note-copy="${escapeHtml(note.id)}">Sao chép ghi chú</button></div>
      </div>
    </article>`;
  }).join("");
  root.querySelectorAll("[data-note-details]").forEach(button=>button.addEventListener("click",()=>{
    const card=button.closest(".vocab-note-card");
    const details=card?.querySelector(".vocab-note-expanded");
    if(!details)return;
    const opening=details.hidden;
    details.hidden=!opening;
    button.setAttribute("aria-expanded",String(opening));
    button.textContent=opening?"Thu gọn":"Chi tiết";
  }));
  root.querySelectorAll("[data-note-delete]").forEach(button=>button.addEventListener("click",async()=>{
    const id=button.dataset.noteDelete;if(!id)return;
    if(!confirm("Xóa ghi chú này khỏi sổ tay?"))return;
    try{
      if(currentUser)await api("/api/notes/"+encodeURIComponent(id),{method:"DELETE",body:"{}"});
      else{guestVocabNotes=guestVocabNotes.filter(note=>note.id!==id);localStorage.setItem(GUEST_VOCAB_NOTES_KEY,JSON.stringify(guestVocabNotes));}
      vocabNotes=vocabNotes.filter(note=>note.id!==id);renderVocabularyNotes();if($("vocabNotesStatus"))$("vocabNotesStatus").textContent="Đã xóa ghi chú.";showToast("Đã xóa ghi chú.");
    }catch(error){showToast("Không xóa được ghi chú: "+error.message);}
  }));
  root.querySelectorAll("[data-note-copy]").forEach(button=>button.addEventListener("click",async()=>{
    const note=items.find(item=>item.id===button.dataset.noteCopy);if(!note)return;
    const text=[note.expression||note.selected_text,"Ý nghĩa: "+note.meaning_vi,note.note?"Ghi chú: "+note.note:"","Cách dùng: "+note.usage,"Ví dụ: "+note.example_en,note.example_vi?"Dịch: "+note.example_vi:""].filter(Boolean).join("\n\n");
    try{await navigator.clipboard.writeText(text);showToast("Đã sao chép ghi chú.");}catch{showToast("Trình duyệt không cho phép sao chép lúc này.");}
  }));
}
