function tokenizeForDiff(text){return String(text||"").match(/\s+|[\p{L}\p{N}_]+|[^\s\p{L}\p{N}_]+/gu)||[];}
function highlightIncorrect(student,revision,explicitSegments){
  const original=String(student||"");
  if(!original||original==="(Bỏ trống)")return escapeHtml(original);
  // Prefer exact spans identified by the model. If unavailable, infer changed tokens
  // by comparing the student's sentence with the suggested revision.
  if(Array.isArray(explicitSegments)&&explicitSegments.length){
    let remaining=original, html="";
    for(const raw of explicitSegments){
      const seg=String(raw||""); if(!seg)continue;
      const at=remaining.indexOf(seg);
      if(at<0)continue;
      html+=escapeHtml(remaining.slice(0,at))+`<mark class="ai-error-highlight">${escapeHtml(seg)}</mark>`;
      remaining=remaining.slice(at+seg.length);
    }
    return html+escapeHtml(remaining);
  }
  if(!revision||String(revision).trim()===original.trim())return escapeHtml(original);
  const a=tokenizeForDiff(original), b=tokenizeForDiff(revision);
  // LCS-based token diff: mark only tokens from the student's answer that are absent
  // from the proposed revision, preserving original spaces and punctuation.
  const n=a.length,m=b.length;
  if(n*m>90000)return escapeHtml(original);
  const dp=Array.from({length:n+1},()=>new Uint32Array(m+1));
  for(let i=n-1;i>=0;i--)for(let j=m-1;j>=0;j--)dp[i][j]=a[i]===b[j]?dp[i+1][j+1]+1:Math.max(dp[i+1][j],dp[i][j+1]);
  let i=0,j=0,out="",bad="";
  const flush=()=>{if(bad){out+=`<mark class="ai-error-highlight">${escapeHtml(bad)}</mark>`;bad="";}};
  while(i<n){
    if(j<m&&a[i]===b[j]){flush();out+=escapeHtml(a[i]);i++;j++;}
    else if(j<m&&dp[i][j+1]>dp[i+1][j]){j++;}
    else {bad+=a[i];i++;}
  }
  flush();return out;
}
function explanationPoints(item){
  if(Array.isArray(item.explanation_points)&&item.explanation_points.length)return item.explanation_points.filter(Boolean);
  const raw=String(item.explanation||"").trim();
  if(!raw)return [];
  // Convert multiline/numbered explanation text into readable bullets; otherwise one bullet.
  const pieces=raw.split(/\n+|(?<=。)\s*|(?<=\.)\s+(?=[A-ZÀ-Ỹ])/u).map(x=>x.replace(/^\s*(?:[-•*]|\d+[.)])\s*/,"").trim()).filter(Boolean);
  return pieces.length?pieces:[raw];
}
function renderFeedback(feedback){
  if(!feedback||typeof feedback!="object")return "";
  const list=(items,renderItem)=>Array.isArray(items)?items.map(renderItem).join(""):"";
  const statusLabel={correct:"Đúng / chấp nhận được",minor_issue:"Cần chỉnh nhẹ",error:"Có lỗi",blank:"Chưa trả lời"};
  const sentenceCards=list(feedback.sentence_feedback,item=>{
    const student=item.student_answer||"(Bỏ trống)";
    const highlighted=highlightIncorrect(student,item.suggested_revision,item.incorrect_segments);
    const points=explanationPoints(item);
    const explanation=points.length?`<div class="ai-explanation"><strong>Giải thích</strong><ul>${points.map(point=>`<li>${escapeHtml(point)}</li>`).join("")}</ul></div>`:"";
    return `<article class="ai-sentence-card"><div class="ai-card-top"><strong>Câu ${escapeHtml(item.sentence_number??"")}</strong><span class="ai-status ${escapeHtml(item.status||"")}">${escapeHtml(statusLabel[item.status]||item.status||"Nhận xét")}</span></div><div class="ai-student-answer"><strong>Bạn viết:</strong><p>${highlighted}</p></div>${item.issue?`<p><strong>Nhận xét:</strong> ${escapeHtml(item.issue)}</p>`:""}${explanation}${item.suggested_revision?`<p class="ai-revision"><strong>Gợi ý sửa:</strong> ${escapeHtml(item.suggested_revision)}</p>`:""}${item.error_type&&item.error_type!=="None"?`<small>Nhóm lỗi: ${escapeHtml(item.error_type)}</small>`:""}</article>`;
  });
  const strengths=list(feedback.strengths,item=>`<li>${escapeHtml(item)}</li>`);
  const errors=list(feedback.recurring_errors,item=>`<article class="ai-error-card"><h4>${escapeHtml(item.title||"Lỗi cần ôn tập")}</h4><ul>${[item.explanation,item.example?"Ví dụ: "+item.example:"",item.practice?"Luyện tập: "+item.practice:""].filter(Boolean).map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul>${item.answer?`<details><summary>Xem đáp án</summary><p>${escapeHtml(item.answer)}</p></details>`:""}</article>`);
  const exercises=list(feedback.exercises,(item,i)=>`<article class="ai-error-card"><h4>Bài tập ${i+1}</h4><ul><li>${escapeHtml(item.question||"")}</li></ul><details><summary>Xem đáp án</summary><p>${escapeHtml(item.answer||"")}</p></details></article>`);
  const plan=list(feedback.improvement_plan,item=>`<li>${escapeHtml(item)}</li>`);
  return `<section class="ai-feedback"><div class="ai-feedback-heading"><div class="eyebrow">AI FEEDBACK</div><h3>Phân tích toàn bài</h3></div><p>${escapeHtml(feedback.overall_summary||"AI đã hoàn tất phân tích.")}</p><p class="ai-highlight-legend"><mark class="ai-error-highlight">Phần tô đỏ</mark> là phần cần kiểm tra hoặc sửa.</p>${strengths?`<h4>Điểm mạnh</h4><ul>${strengths}</ul>`:""}<h4>Nhận xét từng câu</h4><div class="ai-sentence-list">${sentenceCards}</div>${errors?`<h4>Lỗi lặp lại cần ưu tiên</h4><div class="ai-sentence-list">${errors}</div>`:""}${exercises?`<h4>Bài tập củng cố</h4><div class="ai-sentence-list">${exercises}</div>`:""}${plan?`<h4>Kế hoạch cải thiện</h4><ul>${plan}</ul>`:""}<p class="ai-disclaimer">Đây là phản hồi hỗ trợ học tập, không phải điểm IELTS chính thức. Phần tô đỏ được suy ra từ câu sửa đề xuất nếu AI không trả về vị trí lỗi chính xác; hãy kiểm tra ngữ cảnh trước khi áp dụng.</p></section>`;
}
