let pendingLessonId=null;
function findLessonById(id){return LESSONS.find(l=>l.id===id)||customLessons.find(l=>l.id===id)||globalLessons.find(l=>l.id===id)||null;}
function openLessonModeChooser(id){
  const lesson=findLessonById(id);
  if(!lesson){showToast("Không tìm thấy đề này trong thư viện. Hãy tải lại thư viện rồi thử lại.");return;}
  pendingLessonId=id;
  const title=$("lessonModeTitle");if(title)title.textContent="Chọn cách luyện: "+lesson.title;
  const dialog=$("lessonModeDialog");
  if(!dialog)return showToast("Không tìm thấy cửa sổ chọn chế độ trong giao diện.");
  try{if(dialog.open)dialog.close();if(typeof dialog.showModal==="function")dialog.showModal();else dialog.setAttribute("open","");}
  catch(err){dialog.setAttribute("open","");dialog.classList.add("dialog-fallback-open");}
}
function closeLessonModeChooser(){const d=$("lessonModeDialog");if(!d)return;try{if(typeof d.close==="function")d.close();}catch{}d.removeAttribute("open");d.classList.remove("dialog-fallback-open");}
function loadLesson(id,mode="reverse",timerMode="practice"){
  const lesson=findLessonById(id);if(!lesson){showToast("Không tải được đề đã chọn.");return false;}
  const requestedMode=mode==="reverse"?"reverse":"independent";
  const sourceEssay=Array.isArray(lesson.essay)?lesson.essay:[];
  if(requestedMode==="reverse"&&!sourceEssay.length){showToast("Đề này chưa có nội dung câu để luyện dịch ngược. Hãy chọn Tự viết Writing.");return false;}
  saveCurrent();historyReviewMode=false;stopWritingTimer();currentLesson=lesson;
  // Independent writing needs only the prompt; keep a harmless placeholder for
  // the shared renderer when a source item does not contain a sample essay.
  ESSAY=sourceEssay.length?sourceEssay:[{en:"",vi:"",hint:""}];
  answers=Array.isArray(lessonAnswers[id])?lessonAnswers[id]:Array(ESSAY.length).fill("");
  if(answers.length!==ESSAY.length)answers=Array(ESSAY.length).fill("");
  lessonAnswers[id]=answers;active=0;hintShown=false;timerStart=Date.now();
  write("draftwise.lessonAnswers.v1",lessonAnswers);write(STORAGE.answers,answers);
  $("resultPanel").hidden=true;$("independentResultPanel").hidden=true;$("independentEssayInput").value=independentDrafts[id]||"";
  switchView("practice");switchPracticeMode(requestedMode);renderAll();resetWritingTimer();
  if($("brainstormPanel"))$("brainstormPanel").hidden=true;if($("brainstormSummary"))$("brainstormSummary").hidden=true;if($("brainstormStatus"))$("brainstormStatus").textContent="";
  setWritingTimerMode(timerMode);markStudyDraftDirty();showToast("Đã mở bài: "+lesson.title);return true;
}
function startChosenLessonMode(choice){
  const id=pendingLessonId;
  closeLessonModeChooser();pendingLessonId=null;
  if(!id){showToast("Chưa chọn đề luyện. Hãy quay lại thư viện và chọn một bài trước.");return;}
  try{
    const ok=loadLesson(id,choice==="reverse"?"reverse":"independent",choice==="write-exam"?"exam":"practice");
    if(!ok)showToast("Không mở được bài. Hãy tải lại thư viện và thử lại.");
  }catch(error){console.error("Không thể mở chế độ luyện:",error);showToast("Không mở được giao diện làm bài. Hãy tải lại trang; chi tiết lỗi có trong Console.");}
}
