// Library tab visibility is managed in one function; each static tab has a direct click listener.
function activateLibraryTab(tab){
  const selected=tab==="import"?"import":"available";
  document.querySelectorAll("[data-library-tab]").forEach(button=>{const active=button.dataset.libraryTab===selected;button.classList.toggle("active",active);button.setAttribute("aria-selected",String(active));});
  const browse=$("libraryAvailablePanel"),importPanel=$("libraryImportPanel");if(browse)browse.hidden=selected!=="available";if(importPanel)importPanel.hidden=selected!=="import";
  // Keep the tab switch visible for signed-out users too. The import form explains
  // that login is required only when they try to save; do not cover the tab with a modal.
  if(selected==="import"){updateImportOptions();}
  const importNotice=$("importLoginNotice");if(importNotice)importNotice.hidden=!!currentUser;
}
