// WriteWiser v13: per-lesson timer and editable Brainstorm mindmap.
let writingTimerMode="practice", writingTimerRunning=false, writingTimerElapsed=0, writingTimerStartedAt=0, writingTimerInterval=null;
const BRAIN_FIELDS=(function(){const out=[];for(const body of ["body1","body2"])for(const idea of ["idea1","idea2"])out.push(`${body}.${idea}.content`,`${body}.${idea}.explain1`,`${body}.${idea}.explain2`,`${body}.${idea}.example`);return out})();
function defaultBrainIdea(){return {content:"",explain1:"",explain2:"",example:"",expansion:"example"}}
function defaultBrainstorm(){return {schemaVersion:4,body1:{idea1:defaultBrainIdea(),idea2:defaultBrainIdea()},body2:{idea1:defaultBrainIdea(),idea2:defaultBrainIdea()},corrections:{},filled:{},fieldReviews:{},reviewData:null}}
function migrateBrainstormDraft(raw){
 if(raw&&typeof raw==="object"&&raw.body1?.idea1&&typeof raw.body1.idea1==="object"){
   raw.schemaVersion=4;raw.corrections=raw.corrections&&typeof raw.corrections==="object"?raw.corrections:{};raw.filled=raw.filled&&typeof raw.filled==="object"?raw.filled:{};raw.fieldReviews=raw.fieldReviews&&typeof raw.fieldReviews==="object"?raw.fieldReviews:{};raw.reviewData=raw.reviewData&&typeof raw.reviewData==="object"?raw.reviewData:null;return raw;
 }
 const b=defaultBrainstorm();if(!raw||typeof raw!=="object")return b;
 for(const bodyName of ["body1","body2"]){const old=raw[bodyName]||{};for(const [index,slot] of [[1,"idea1"],[2,"idea2"]]){const target=b[bodyName][slot];target.content=String(old[slot]||"");target.explain1=String(old[index===1?"explain1":"explain2"]||"");target.example=String(old[index===1?"example1":"example2"]||"");target.expansion="example";}}
 b.corrections=raw.corrections&&typeof raw.corrections==="object"?raw.corrections:{};b.filled=raw.filled&&typeof raw.filled==="object"?raw.filled:{};b.reviewSummary=String(raw.reviewSummary||"");return b;
}
function getBrainstorm(){if(!brainstormDrafts[currentLesson.id])brainstormDrafts[currentLesson.id]=defaultBrainstorm();brainstormDrafts[currentLesson.id]=migrateBrainstormDraft(brainstormDrafts[currentLesson.id]);return brainstormDrafts[currentLesson.id]}
function saveBrainstorm(){brainstormDrafts[currentLesson.id]=getBrainstorm();localStorage.setItem("writewiser.brainstormDrafts.v13",JSON.stringify(brainstormDrafts));scheduleSync()}
function getPath(obj,path){return path.split(".").reduce((o,k)=>o&&o[k],obj)}
function setPath(obj,path,value){const bits=path.split(".");let o=obj;for(const k of bits.slice(0,-1))o=o[k]||(o[k]={});o[bits.at(-1)]=value}
function brainPathLabel(path){
 const parts=String(path||"").split(".");const body=parts[0]==="body1"?"Body 1":parts[0]==="body2"?"Body 2":parts[0]||"Mindmap";const idea=parts[1]==="idea1"?"Idea 1":parts[1]==="idea2"?"Idea 2":parts[1]||"";const fieldMap={content:"Idea · ý chính",explain1:"Explain 1",example:"Example",explain2:"Explain 2"};return [body,idea,fieldMap[parts[2]]||parts[2]||""].filter(Boolean).join(" · ");
}
function highlightBrainText(value,issues){
 const text=String(value||"");const matches=[];let cursor=0;
 for(const issue of [...(issues||[])].sort((a,b)=>String(b.segment||"").length-String(a.segment||"").length)){
  const segment=String(issue.segment||"");if(!segment)continue;let pos=text.indexOf(segment,0);while(pos>=0&&matches.some(m=>pos<m.end&&pos+segment.length>m.start))pos=text.indexOf(segment,pos+1);if(pos>=0)matches.push({start:pos,end:pos+segment.length,segment});
 }
 matches.sort((a,b)=>a.start-b.start);let out="";for(const m of matches){out+=escapeHtml(text.slice(cursor,m.start))+`<mark class="brain-wrong-segment">${escapeHtml(text.slice(m.start,m.end))}</mark>`;cursor=m.end;}return out+escapeHtml(text.slice(cursor));
}
function brainFieldReviewMarkup(path,value,fieldReview){
 if(!fieldReview)return "";const issues=Array.isArray(fieldReview.issues)?fieldReview.issues:[];
 if(issues.length){
  const rows=issues.map(issue=>`<div class="brain-issue-row"><div class="brain-issue-pair"><span class="brain-issue-wrong">${escapeHtml(issue.segment||"")}</span><span class="brain-issue-arrow" aria-hidden="true">→</span><span class="brain-issue-correct">${escapeHtml(issue.replacement||"")}</span></div><small>${issue.dimension==="idea"?"Độ sát đề":"Dùng từ/collocation"}${issue.reason?" · "+escapeHtml(issue.reason):""}</small></div>`).join("");
  return `<div class="brain-field-review needs-revision"><div class="brain-review-caption">Phần cần xem lại · chỉ đánh dấu đúng từ/cụm có vấn đề</div><div class="brain-reviewed-text">${highlightBrainText(value,issues)}</div><div class="brain-issue-list">${rows}</div>${fieldReview.note?`<p class="brain-review-note">${escapeHtml(fieldReview.note)}</p>`:""}<p class="brain-review-rest">✓ Các phần còn lại chưa ghi nhận vấn đề về từ vựng hoặc độ sát đề. Ngữ pháp không được chấm ở mục này.</p><button type="button" class="button secondary apply-brain-segment-corrections" data-path="${escapeHtml(path)}">Áp dụng các sửa đề xuất</button></div>`;
 }
 return `<div class="brain-field-review is-correct"><strong>✓ Đã phù hợp</strong><span>${escapeHtml(fieldReview.note||"Từ vựng và ý tưởng phù hợp trong phạm vi rà soát. Không đánh giá ngữ pháp.")}</span></div>`;
}
function brainField(path,label,placeholder="Ghi ý ngắn gọn…",required=false){
 const b=getBrainstorm(),val=String(getPath(b,path)||""),cor=b.corrections?.[path],fieldReview=b.fieldReviews?.[path];
 const legacyCorrection=!fieldReview&&cor?`<div class="inline-correction"><span class="wrong">${escapeHtml(cor.original||val||"(trống)")}</span><span class="correct">${escapeHtml(cor.corrected||"")}</span><button type="button" class="button secondary apply-brain-correction" data-path="${path}">Áp dụng sửa</button>${cor.reason?`<small>${escapeHtml(cor.reason)}</small>`:""}</div>`:"";
 return `<div class="mind-field" data-field="${path}"><label>${label}${required?' <span class="required-mark">· bắt buộc</span>':""}</label><textarea data-brain-path="${path}" rows="2" placeholder="${placeholder}">${escapeHtml(val)}</textarea>${fieldReview?brainFieldReviewMarkup(path,val,fieldReview):legacyCorrection}</div>`;
}
function renderBrainstormSummary(reviewData){
 const root=$("brainstormSummary");if(!root)return;const b=getBrainstorm();const data=reviewData&&typeof reviewData==="object"?reviewData:b.reviewData;
 if(!data||typeof data!=="object"){root.textContent=String(b.reviewSummary||"");root.hidden=!root.textContent.trim();return;}
 const categories=data.summary_categories&&typeof data.summary_categories==="object"?data.summary_categories:{};
 const renderList=(key,title,kind)=>{const items=Array.isArray(categories[key])?categories[key]:[];let body="";if(!items.length){body=`<p class="brain-summary-empty">${key==="valid_vocabulary"||key==="relevant_ideas"?"Chưa có mục được ghi nhận trong nhóm này.":"Không ghi nhận mục cần sửa trong nhóm này."}</p>`;}else{body=`<ul>${items.slice(0,20).map(item=>{const label=brainPathLabel(item.path);let main="";if(kind==="vocab")main=`<strong>${escapeHtml(item.segment||"")}</strong> — ${escapeHtml(item.reason||"")}`;else if(kind==="fix")main=`<span class="brain-summary-red">${escapeHtml(item.segment||"")}</span> <span aria-hidden="true">→</span> <span class="brain-summary-green">${escapeHtml(item.replacement||"")}</span><p>${escapeHtml(item.reason||"")}</p>`;else if(kind==="idea")main=`<strong>${escapeHtml(item.idea||"")}</strong><p>${escapeHtml(item.reason||"")}</p>`;else main=`<strong>${escapeHtml(item.idea||item.segment||"")}</strong><p>${escapeHtml(item.reason||"")}${item.suggestion?" · Gợi ý: "+escapeHtml(item.suggestion):""}</p>`;return `<li>${main}<small>${escapeHtml(label)}</small></li>`;}).join("")}</ul>`;}return `<section class="brain-summary-section"><h4>${title}</h4>${body}</section>`;};
 root.innerHTML=`<div class="brain-summary-overview"><strong>Kết luận chung</strong><p>${escapeHtml(data.overall_summary||b.reviewSummary||"Đã hoàn tất rà soát.")}</p><small>Phạm vi đánh giá: lựa chọn từ/cụm từ và mức độ sát đề. Không chấm ngữ pháp.</small></div><div class="brain-summary-grid">${renderList("valid_vocabulary","Từ vựng/cụm từ dùng chuẩn","vocab")}${renderList("vocabulary_to_fix","Từ vựng/cụm từ cần sửa","fix")}${renderList("relevant_ideas","Idea phù hợp đề","idea")}${renderList("irrelevant_ideas","Idea chưa sát đề","offtopic")}${renderList("changes_needed","Các chỗ cần sửa","fix")}</div>`;root.hidden=false;
}
function brainIdeaFields(body,idea,label){
 const prefix=`${body}.${idea}`,b=getBrainstorm(),expansion=getPath(b,prefix+".expansion")==="explain2"?"explain2":"example";
 return `<section class="mind-idea"><h4>${label}</h4>${brainField(prefix+".content","Idea · ý chính","Nêu một luận điểm chính",true)}${brainField(prefix+".explain1","Explain 1","Giải thích đầu tiên cho ý chính",true)}<div class="mind-expansion-select"><label for="exp-${body}-${idea}">Cách phát triển thêm</label><select id="exp-${body}-${idea}" data-brain-expansion="${prefix}.expansion"><option value="example" ${expansion==="example"?"selected":""}>Example · ví dụ minh họa</option><option value="explain2" ${expansion==="explain2"?"selected":""}>Explain 2 · giải thích thêm</option></select></div><div data-expansion-field="${prefix}" data-expansion-kind="example" ${expansion!=="example"?"hidden":""}>${brainField(prefix+".example","Example","Đưa ví dụ cụ thể")}</div><div data-expansion-field="${prefix}" data-expansion-kind="explain2" ${expansion!=="explain2"?"hidden":""}>${brainField(prefix+".explain2","Explain 2","Mở rộng cơ chế / hệ quả")}</div></section>`;
}
function invalidateBrainstormReview(){const b=getBrainstorm();b.fieldReviews={};b.reviewData=null;b.reviewSummary="";b.corrections={};const summary=$("brainstormSummary");if(summary){summary.hidden=true;summary.innerHTML=""}}
function renderBrainstorm(){
 const root=$("brainstormMindmap");if(!root)return;const b=getBrainstorm();
 root.innerHTML=`<div class="mindmap-root"><div class="mindmap-node center-node"><span class="mind-label">ĐỀ BÀI — KHÔNG CẦN NHẬP LẠI</span><p>${escapeHtml(currentLesson.question)}</p></div><div class="mindmap-branches"><section class="mind-branch branch-one"><h3>BODY 1</h3>${brainIdeaFields("body1","idea1","Idea 1")}${brainIdeaFields("body1","idea2","Idea 2")}</section><section class="mind-branch branch-two"><h3>BODY 2</h3>${brainIdeaFields("body2","idea1","Idea 1")}${brainIdeaFields("body2","idea2","Idea 2")}</section></div></div>`;
 root.querySelectorAll("textarea[data-brain-path]").forEach(el=>el.addEventListener("input",()=>{const b=getBrainstorm();const hadReview=Object.keys(b.fieldReviews||{}).length||b.reviewData||b.reviewSummary;setPath(b,el.dataset.brainPath,el.value);if(hadReview){invalidateBrainstormReview();root.querySelectorAll(".brain-field-review,.inline-correction").forEach(node=>node.remove());const status=$("brainstormStatus");if(status)status.textContent="Mindmap đã thay đổi; hãy nộp lại để cập nhật nhận xét.";}saveBrainstorm();markStudyDraftDirty()}));
 root.querySelectorAll("select[data-brain-expansion]").forEach(el=>el.addEventListener("change",()=>{setPath(getBrainstorm(),el.dataset.brainExpansion,el.value);const fieldPrefix=el.dataset.brainExpansion.replace(/\.expansion$/,"");root.querySelectorAll(`[data-expansion-field="${fieldPrefix}"]`).forEach(box=>box.hidden=box.dataset.expansionKind!==el.value);const hadReview=Object.keys(getBrainstorm().fieldReviews||{}).length||getBrainstorm().reviewData||getBrainstorm().reviewSummary;invalidateBrainstormReview();if(hadReview){root.querySelectorAll(".brain-field-review,.inline-correction").forEach(node=>node.remove());const status=$("brainstormStatus");if(status)status.textContent="Loại trường phát triển đã thay đổi; hãy nộp lại để cập nhật nhận xét.";}saveBrainstorm()}));
 root.querySelectorAll(".apply-brain-correction").forEach(btn=>btn.addEventListener("click",()=>{const path=btn.dataset.path,cor=getBrainstorm().corrections?.[path];if(!cor)return;setPath(getBrainstorm(),path,cor.corrected||"");delete getBrainstorm().corrections[path];invalidateBrainstormReview();saveBrainstorm();renderBrainstorm();showToast("Đã áp dụng chỉnh sửa vào mindmap.")}));
 root.querySelectorAll(".apply-brain-segment-corrections").forEach(btn=>btn.addEventListener("click",()=>{const path=btn.dataset.path,b=getBrainstorm(),fieldReview=b.fieldReviews?.[path];if(!fieldReview||!Array.isArray(fieldReview.issues))return;let value=String(getPath(b,path)||"");const matches=fieldReview.issues.map(issue=>({...issue,index:value.indexOf(String(issue.segment||""))})).filter(issue=>issue.index>=0).sort((a,b)=>b.index-a.index);for(const issue of matches){const segment=String(issue.segment||"");value=value.slice(0,issue.index)+String(issue.replacement||"")+value.slice(issue.index+segment.length)}setPath(b,path,value);invalidateBrainstormReview();saveBrainstorm();renderBrainstorm();showToast("Đã áp dụng các sửa đổi từ/cụm từ được chọn.")}));
 renderBrainstormSummary(b.reviewData);
}
function formatTimer(seconds){seconds=Math.max(0,Math.floor(seconds));return String(Math.floor(seconds/60)).padStart(2,"0")+":"+String(seconds%60).padStart(2,"0")}
function timerElapsedNow(){return writingTimerElapsed+(writingTimerRunning?Math.floor((Date.now()-writingTimerStartedAt)/1000):0)}
function updateWritingTimer(){const display=$("writingTimerDisplay");if(!display)return;const isExam=writingTimerMode==="exam";const duration=Number($("writingExamDuration")?.value|| (String(currentLesson.task).includes("Task 1")?20:40))*60;const elapsed=timerElapsedNow();const shown=isExam?Math.max(0,duration-elapsed):elapsed;display.textContent=formatTimer(shown);display.classList.toggle("timer-danger",isExam&&shown<=300);const state=$("writingTimerState"),startBtn=$("writingTimerStart");if(state)state.textContent=writingTimerRunning?(isExam?"Đang thi":"Đang luyện"):elapsed?"Đã tạm dừng":"Chưa bắt đầu";if(startBtn)startBtn.textContent=writingTimerRunning?"Tạm dừng":(elapsed?"Tiếp tục":"Bắt đầu");if(isExam&&shown===0&&writingTimerRunning){writingTimerElapsed=duration;writingTimerRunning=false;clearInterval(writingTimerInterval);writingTimerInterval=null;display.textContent="00:00";if(state)state.textContent="Đã hết giờ — bài viết vẫn được giữ lại";if(startBtn)startBtn.textContent="Bắt đầu lại";showToast("Đã hết giờ. Bài viết vẫn được giữ nguyên để bạn nộp.")}}
function stopWritingTimer(){if(writingTimerRunning){writingTimerElapsed=timerElapsedNow();writingTimerRunning=false}clearInterval(writingTimerInterval);writingTimerInterval=null;updateWritingTimer()}
function startWritingTimer(){if(writingTimerRunning)return;const isExam=writingTimerMode==="exam";const duration=Number($("writingExamDuration")?.value|| (String(currentLesson.task).includes("Task 1")?20:40))*60;if(isExam&&writingTimerElapsed>=duration)writingTimerElapsed=0;writingTimerStartedAt=Date.now();writingTimerRunning=true;writingTimerInterval=setInterval(updateWritingTimer,250);updateWritingTimer()}
function resetWritingTimer(){stopWritingTimer();writingTimerElapsed=0;writingTimerStartedAt=0;updateWritingTimer()}
function refreshExamDurations(){const el=$("writingExamDuration");if(!el)return;const opts=String(currentLesson.task).includes("Task 1")?[15,20,25,30]:[35,40,45,50];const previous=Number(el.value);el.innerHTML=opts.map(n=>`<option value="${n}">${n} phút</option>`).join("");el.value=opts.includes(previous)?String(previous):String(opts.includes(Number(currentLesson.time))?currentLesson.time:opts[1]);}
function setWritingTimerMode(mode){stopWritingTimer();refreshExamDurations();writingTimerMode=mode==="exam"?"exam":"practice";$("timerPracticeButton")?.classList.toggle("active",writingTimerMode==="practice");$("timerExamButton")?.classList.toggle("active",writingTimerMode==="exam");if($("writingExamDuration"))$("writingExamDuration").hidden=writingTimerMode!=="exam";const brainBtn=$("brainstormOpenButton");if(brainBtn)brainBtn.hidden=writingTimerMode!=="practice";if(writingTimerMode!=="practice"&&$("brainstormPanel"))$("brainstormPanel").hidden=true;resetWritingTimer();}
function rootFocusBrain(path){document.querySelector(`[data-brain-path="${path}"]`)?.focus()}
async function submitBrainstorm(){
 const b=getBrainstorm();
 // Only the two marked-required fields are validated. The selected Example/Explain 2 is optional and can remain blank.
 for(const bodyName of ["body1","body2"])for(const ideaName of ["idea1","idea2"]){const idea=b[bodyName][ideaName],second=idea.expansion==="explain2"?idea.explain2:idea.example;const any=String(idea.content||"").trim()||String(idea.explain1||"").trim()||String(second||"").trim();if(any){if(!String(idea.content||"").trim()){showToast(`${bodyName.toUpperCase()} ${ideaName}: hãy nhập Idea trước.`);rootFocusBrain(`${bodyName}.${ideaName}.content`);return;}if(!String(idea.explain1||"").trim()){showToast(`${bodyName.toUpperCase()} ${ideaName}: Explain 1 là bắt buộc.`);rootFocusBrain(`${bodyName}.${ideaName}.explain1`);return;}}}
 saveBrainstorm();const btn=$("brainstormSubmitButton"),status=$("brainstormStatus");btn.disabled=true;status.textContent="AI đang kiểm tra độ phù hợp của từ vựng và mức độ sát đề (không chấm ngữ pháp)…";
 try{const r=await api("/api/brainstorm-review",{method:"POST",body:JSON.stringify({task:currentLesson.task,question:currentLesson.question,type:currentLesson.type,topic:currentLesson.topic,mindmap:b})});
   const data=r.review||{};const filled=data.fill_required_blanks||{};let count=0;
   for(const [path,value] of Object.entries(filled)){if(BRAIN_FIELDS.includes(path)&&(path.endsWith(".content")||path.endsWith(".explain1"))){if(!String(getPath(b,path)||"").trim()&&typeof value==="string"&&value.trim()){setPath(b,path,value.trim());count++}}}
   b.fieldReviews=data.field_reviews&&typeof data.field_reviews==="object"?data.field_reviews:{};for(const path of Object.keys(filled)){if(BRAIN_FIELDS.includes(path)&&(path.endsWith(".content")||path.endsWith(".explain1"))&&String(getPath(b,path)||"").trim()&&!data.field_reviews?.[path])b.fieldReviews[path]={status:"correct",note:"Đây là gợi ý AI tạo cho ô bắt buộc còn trống. Hãy đọc lại và chỉnh theo ý bạn; phạm vi rà soát không bao gồm ngữ pháp.",issues:[]};}b.corrections={};b.reviewSummary=String(data.overall_summary||"");b.reviewData={overall_summary:b.reviewSummary,summary_categories:data.summary_categories||{}};b.reviewedAt=new Date().toISOString();saveBrainstorm();renderBrainstorm();
   status.textContent=`Đã rà soát từ vựng và độ sát đề. AI gợi ý ${count} ô bắt buộc còn trống; ô không bắt buộc để trống được bỏ qua. Ngữ pháp không được chấm.`;
   renderBrainstormSummary(b.reviewData);showToast("Đã cập nhật nhận xét từ vựng và ý tưởng.");
 }catch(e){status.textContent=e.message;showToast("Chưa thể nhận xét Brainstorm: "+e.message)}finally{btn.disabled=false}
}
function initV13WritingTools(){
 $("timerPracticeButton")?.addEventListener("click",()=>setWritingTimerMode("practice"));$("timerExamButton")?.addEventListener("click",()=>setWritingTimerMode("exam"));
 $("writingExamDuration")?.addEventListener("change",resetWritingTimer);$("writingTimerStart")?.addEventListener("click",()=>writingTimerRunning?stopWritingTimer():startWritingTimer());$("writingTimerReset")?.addEventListener("click",resetWritingTimer);
 $("brainstormOpenButton")?.addEventListener("click",()=>{const panel=$("brainstormPanel");panel.hidden=!panel.hidden;if(!panel.hidden){renderBrainstorm();panel.scrollIntoView({behavior:"smooth",block:"start"})}});$("brainstormSubmitButton")?.addEventListener("click",submitBrainstorm);
 $("checkScoringPromptButton")?.addEventListener("click",async()=>{const out=$("scoringPromptStatus");out.textContent="Đang kiểm tra prompt trên máy chủ…";try{const r=await api("/api/scoring-status");out.textContent=`${r.masterPromptLoaded?"Đã nạp prompt":"Chưa nạp prompt"} · ${r.promptChars} ký tự · SHA-256 ${r.promptSha256} · Điểm tiêu chí: số nguyên 0–9 · v${r.version}`;}catch(e){out.textContent="Không xác minh được: "+e.message}});
 setWritingTimerMode("practice");
}

